  chatMessageId: 'srv-1',
  occurredAt: '2026-01-01T00:00:00Z',
  serverRevision: 1,
  createdAt: '2026-01-01T00:00:00Z',
  updatedAt: '2026-01-01T00:00:00Z',
);

void main() {
  late _FakeChatRepository fakeRepository;
  late FakeConnectivityWatcher fakeConnectivityWatcher;

