  testWidgets(
    'review: dismissing the Insight card never visibly shifts scroll '
    'position when the user had deliberately scrolled away from the '
    "bottom — ChatReady.restoreScrollOffset being unchanged (already "
    "covered at the cubit level) doesn't by itself prove the ListView's "
    'own rendered offset stays put',
    (tester) async {
      final repository = _FakeChatRepository()
        ..generateInsightResult = right(
          const ChatInsight(id: 'ins-1', content: 'um padrão notado'),
        );
      final cubit = await pumpScreen(tester, repository);
      await tester.pumpAndSettle();

      // 3 rounds (15 exchanges) of real sends/replies, so there's
      // comfortably more scrollable content than the default viewport
      // height — enough margin that moving away from the bottom below
      // doesn't risk scrolling the Insight card itself (the list's
      // trailing item) out of view.
      await sendFiveMessages(tester, repository);
      await sendFiveMessages(tester, repository);
      await sendFiveMessages(tester, repository);
      expect(find.byType(InsightCard), findsOneWidget);
      // ignore: avoid_print
      print('DEBUG messages=${(cubit.state as ChatReady).messages.length}');

      // Jump away from the bottom by a fixed, deterministic amount —
      // comfortably past `_scrollToBottomSoon`'s own 80px "near bottom"
      // threshold, so dismissing doesn't itself trigger an unrelated
      // jump-to-bottom that would mask the bug this test exists to
      // catch, but small enough the Insight card stays on screen.
      final controller = tester.widget<ListView>(find.byType(ListView)).controller!;
      final maxScrollExtent = controller.position.maxScrollExtent;
      final cardHeight = tester.getSize(find.byType(InsightCard)).height;
      // ignore: avoid_print
      print('DEBUG maxScrollExtent=$maxScrollExtent offset=${controller.offset} cardHeight=$cardHeight');
      controller.jumpTo(maxScrollExtent - 150);
      await tester.pumpAndSettle();
      // ignore: avoid_print
      print('DEBUG after jump offset=${controller.offset} max=${controller.position.maxScrollExtent}');

      expect(find.byType(InsightCard), findsOneWidget);
      expect(maxScrollExtent - controller.offset, greaterThan(80));
      final offsetBeforeDismiss = controller.offset;

      await tester.tap(
        find.descendant(
          of: find.byType(InsightCard),
          matching: find.byIcon(Icons.close),
        ),
      );
      await tester.pumpAndSettle();

      expect(find.byType(InsightCard), findsNothing);
      expect(controller.offset, offsetBeforeDismiss);
    },
  );
}

